<div class="d-flex flex-wrap gap-2 mb-3"><h2 class="h4">余额明细</h2><div class="ms-auto"><a class="btn btn-primary" href="<?= h(url_to('admin/balance/adjust')) ?>">单用户调整</a> <a class="btn btn-outline-primary" href="<?= h(url_to('admin/balance/batch')) ?>">批量调整</a></div></div><form class="row g-2 mb-3"><div class="col-md-4"><input class="form-control" name="kw" value="<?= h($kw) ?>" placeholder="用户ID、类型、备注"></div><div class="col-md-3"><input class="form-control" name="type" value="<?= h($type) ?>" placeholder="流水类型"></div><div class="col-auto"><button class="btn btn-outline-secondary">筛选</button></div></form><div class="table-responsive table-card"><table class="table"><thead><tr><th>用户</th><th>变动</th><th>余额</th><th>类型</th><th>原因</th><th>操作人</th><th>时间</th></tr></thead><tbody><?php foreach ($list as $r): ?><tr><td><?= h($r['user_id']) ?></td><td class="<?= $r['amount'] >= 0 ? 'text-success' : 'text-danger' ?>"><?= h(money($r['amount'])) ?></td><td><?= h(money($r['balance'])) ?></td><td><?= h(balance_type_name($r['type'])) ?></td><td><?= h($r['remark']) ?></td><td><?= h($r['operator']) ?></td><td><?= h(fmt_time($r['create_time'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?= pager_html($total, $page, $size, ['kw' => $kw, 'type' => $type]) ?>